/**
 * generate-mobile-icons.mjs
 * Produces all Expo/React Native icon assets for civicfix-mobile
 * from two source images generated by the brand designer.
 *
 * Run from the civicfix-mobile directory:
 *   node generate-mobile-icons.mjs
 *
 * It reads from:
 *   ./icon-source-full.png     — full icon (teal bg + white mark)   [1024×1024]
 *   ./icon-source-fg.png       — foreground only (transparent bg)   [1024×1024]
 *
 * Writes to assets/images/:
 *   icon.png                   1024×1024  universal app icon
 *   android-icon-foreground.png 1024×1024 adaptive foreground layer
 *   android-icon-monochrome.png 1024×1024 white mark on transparent (theme icon)
 *   android-icon-background.png 1024×1024 solid teal fill (adaptive background)
 *   splash-icon.png             512×512   splash screen mark
 *   favicon.png                 64×64     web favicon
 */

import sharp from 'sharp';
import { mkdirSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT = join(__dirname, 'assets', 'images');
mkdirSync(OUT, { recursive: true });

const FULL_SRC = join(__dirname, 'icon-source-full.png');
const FG_SRC   = join(__dirname, 'icon-source-fg.png');

// Brand primary teal
const TEAL = { r: 11, g: 79, b: 108, alpha: 1 };

async function resize(src, size, dest) {
  await sharp(src).resize(size, size).png().toFile(dest);
  console.log(`✅  ${size}×${size}  →  ${dest.replace(__dirname, '.')}`);
}

async function solidBackground(size, dest) {
  await sharp({
    create: { width: size, height: size, channels: 4, background: TEAL },
  }).png().toFile(dest);
  console.log(`✅  ${size}×${size} teal bg  →  ${dest.replace(__dirname, '.')}`);
}

async function makeMonochrome(size, dest) {
  // Render foreground PNG, desaturate to pure white (greyscale → white via tint)
  // We composite the foreground on transparent then convert non-transparent pixels to white.
  const fg = await sharp(FG_SRC)
    .resize(size, size)
    .greyscale()           // flatten to single channel
    .toBuffer();

  // Re-colorise to white: multiply greyscale by (255,255,255)
  await sharp(fg)
    .tint({ r: 255, g: 255, b: 255 })
    .png()
    .toFile(dest);
  console.log(`✅  ${size}×${size} mono  →  ${dest.replace(__dirname, '.')}`);
}

(async () => {
  try {
    // 1. Universal app icon (full branded square)
    await resize(FULL_SRC, 1024, join(OUT, 'icon.png'));

    // 2. Android adaptive foreground (mark on transparent bg)
    await resize(FG_SRC, 1024, join(OUT, 'android-icon-foreground.png'));

    // 3. Android monochrome (notification / themed icon)
    await makeMonochrome(1024, join(OUT, 'android-icon-monochrome.png'));

    // 4. Android adaptive background (solid teal)
    await solidBackground(1024, join(OUT, 'android-icon-background.png'));

    // 5. Splash screen icon
    await resize(FULL_SRC, 512, join(OUT, 'splash-icon.png'));

    // 6. Web favicon (used by Expo web)
    await resize(FULL_SRC, 64, join(OUT, 'favicon.png'));

    console.log('\n🎉  All mobile icons generated successfully.\n');
  } catch (err) {
    console.error('\n❌  Icon generation failed:', err.message);
    console.error('Make sure icon-source-full.png and icon-source-fg.png exist in', __dirname);
    process.exit(1);
  }
})();
